const data = $input.first().json;
const date = data.date || new Date().toISOString().slice(0,10);
const stockAlerts = data.stock_alerts || [];
const unmatched = data.unmatched_skus || {};
const fbaMissing = unmatched.fba_unmatched || [];
const awdMissing = unmatched.awd_unmatched || [];

const totalIssues = stockAlerts.length + fbaMissing.length + awdMissing.length;

// ── HTML Email ──────────────────────────────────────────────────────────────
let html = `<div style="font-family:Arial,sans-serif;max-width:820px;color:#333">`;
html += `<h2 style="border-bottom:2px solid #e0e0e0;padding-bottom:8px">🔔 AWD 補貨日報 — ${date}</h2>`;

// 1. 庫存斷貨警示
if (stockAlerts.length > 0) {
  html += `<h3 style="color:#c0392b">📦 庫存警示（${stockAlerts.length} 個 SKU）</h3>`;
  html += `<table cellpadding="8" cellspacing="0" style="border-collapse:collapse;width:100%;font-size:13px">`;
  html += `<thead><tr style="background:#f5f5f5;border:1px solid #ddd">`;
  html += `<th style="border:1px solid #ddd">Collection</th>`;
  html += `<th style="border:1px solid #ddd">SKU</th>`;
  html += `<th style="border:1px solid #ddd">Product Name</th>`;
  html += `<th style="border:1px solid #ddd">警示狀態</th>`;
  html += `<th style="border:1px solid #ddd">FBA 現貨</th>`;
  html += `<th style="border:1px solid #ddd">AWD 現貨</th>`;
  html += `<th style="border:1px solid #ddd">30日銷量</th>`;
  html += `</tr></thead><tbody>`;
  for (const r of stockAlerts) {
    const bg = r.stock_alert.startsWith('🔴') ? '#fdecea'
             : r.stock_alert.startsWith('🟠') ? '#fff3e0'
             : '#fffde7';
    html += `<tr style="background:${bg}">`;
    html += `<td style="border:1px solid #ddd">${r.collection||'-'}</td>`;
    html += `<td style="border:1px solid #ddd"><b>${r.sku}</b></td>`;
    html += `<td style="border:1px solid #ddd">${r.product_name||'-'}</td>`;
    html += `<td style="border:1px solid #ddd">${r.stock_alert}</td>`;
    html += `<td style="border:1px solid #ddd;text-align:center">${r.fba_available||0}</td>`;
    html += `<td style="border:1px solid #ddd;text-align:center">${r.awd_available||0}</td>`;
    html += `<td style="border:1px solid #ddd;text-align:center">${r.sales_qty||0}</td>`;
    html += `</tr>`;
  }
  html += `</tbody></table><br/>`;
}

// 2. Anchor 未對應 SKU（FBA 有但 product_catalog 沒有）
if (fbaMissing.length > 0) {
  html += `<h3 style="color:#d35400">⚠️ FBA 有庫存但 Anchor 未建立（${fbaMissing.length} 個）</h3>`;
  html += `<table cellpadding="8" cellspacing="0" style="border-collapse:collapse;width:100%;font-size:13px">`;
  html += `<thead><tr style="background:#f5f5f5">`;
  html += `<th style="border:1px solid #ddd">SKU</th><th style="border:1px solid #ddd">ASIN</th>`;
  html += `<th style="border:1px solid #ddd">Product Name</th><th style="border:1px solid #ddd">FBA 現貨</th><th style="border:1px solid #ddd">FBA Inbound</th>`;
  html += `</tr></thead><tbody>`;
  for (const r of fbaMissing) {
    html += `<tr><td style="border:1px solid #ddd">${r.sku}</td><td style="border:1px solid #ddd">${r.asin||'-'}</td>`;
    html += `<td style="border:1px solid #ddd">${r.product_name||'-'}</td>`;
    html += `<td style="border:1px solid #ddd;text-align:center">${r.fba_available||0}</td>`;
    html += `<td style="border:1px solid #ddd;text-align:center">${r.fba_inbound||0}</td></tr>`;
  }
  html += `</tbody></table><br/>`;
}

// 3. Anchor 未對應 SKU（AWD 有但 product_catalog 沒有）
if (awdMissing.length > 0) {
  html += `<h3 style="color:#d35400">⚠️ AWD 有庫存但 Anchor 未建立（${awdMissing.length} 個）</h3>`;
  html += `<table cellpadding="8" cellspacing="0" style="border-collapse:collapse;width:100%;font-size:13px">`;
  html += `<thead><tr style="background:#f5f5f5">`;
  html += `<th style="border:1px solid #ddd">SKU</th><th style="border:1px solid #ddd">AWD 現貨</th>`;
  html += `<th style="border:1px solid #ddd">AWD Inbound</th><th style="border:1px solid #ddd">AWD Outbound</th>`;
  html += `</tr></thead><tbody>`;
  for (const r of awdMissing) {
    html += `<tr><td style="border:1px solid #ddd">${r.sku}</td>`;
    html += `<td style="border:1px solid #ddd;text-align:center">${r.awd_available||0}</td>`;
    html += `<td style="border:1px solid #ddd;text-align:center">${r.awd_inbound||0}</td>`;
    html += `<td style="border:1px solid #ddd;text-align:center">${r.awd_outbound||0}</td></tr>`;
  }
  html += `</tbody></table><br/>`;
}

html += `<p style="color:#999;font-size:11px;border-top:1px solid #eee;padding-top:8px">`;
html += `此郵件由 n8n AWD Replenishment Pipeline 自動發送 | ${new Date().toISOString()}</p></div>`;

// ── Subject ────────────────────────────────────────────────────────────────
const parts = [];
if (stockAlerts.length > 0) parts.push(`${stockAlerts.length} 個庫存警示`);
if (fbaMissing.length + awdMissing.length > 0) parts.push(`${fbaMissing.length + awdMissing.length} 個未對應 SKU`);
const subject = `[AWD 補貨] ${date} — ${parts.join(' + ')}`;

return [{ json: { subject, html_body: html, total_issues: totalIssues } }];
